INSERT INTO jobs(title, department, location, description, requirements)
SELECT d.title, d.department, d.location, d.description, d.requirements
FROM demo_jobs d
WHERE NOT EXISTS (
  SELECT 1 FROM jobs j WHERE lower(j.title)=lower(d.title) AND lower(j.department)=lower(d.department)
);
